const P=(p,h=0)=>new THREE.Vector3(p.X??p.x,h,-(p.Y??p.y));
function label(text,p,kind='',group='map'){const element=document.createElement('div');element.className='label '+kind;element.textContent=text;$('labels').append(element);const item={element,p,group};labels.push(item);return item;}
