async function readModel(file){const response=await fetch(file);if(!response.ok)throw new Error('Mesh unavailable: '+file);let buffer=await response.arrayBuffer();const bytes=new Uint8Array(buffer);if(bytes[0]===31&&bytes[1]===139){const stream=new Blob([buffer]).stream().pipeThrough(new DecompressionStream('gzip'));buffer=await new Response(stream).arrayBuffer();}const length=new DataView(buffer).getUint32(0,true),header=JSON.parse(new TextDecoder().decode(new Uint8Array(buffer,4,length))),base=4+length,group=new THREE.Group();group.name=header.name;
 for(const chunk of header.chunks){const geometry=new THREE.BufferGeometry(),position=new Float32Array(buffer,base+chunk.position.offset,chunk.position.count),normal=new Int16Array(buffer,base+chunk.normal.offset,chunk.normal.count),index=new Uint32Array(buffer,base+chunk.index.offset,chunk.index.count);for(let i=2;i<position.length;i+=3){position[i]*=-1;normal[i]*=-1;}for(let i=0;i<index.length;i+=3){const v=index[i+1];index[i+1]=index[i+2];index[i+2]=v;}
 geometry.setAttribute('position',new THREE.BufferAttribute(position,3));geometry.setAttribute('normal',new THREE.BufferAttribute(normal,3,true));geometry.setAttribute('uv',new THREE.BufferAttribute(new Float32Array(buffer,base+chunk.uv.offset,chunk.uv.count),2));geometry.setAttribute('color',new THREE.BufferAttribute(new Uint8Array(buffer,base+chunk.color.offset,chunk.color.count),4,true));geometry.setIndex(new THREE.BufferAttribute(index,1));const materials=[];chunk.groups.forEach((g,i)=>{geometry.addGroup(g.start,g.count,i);materials.push(palette.get(g.material));});geometry.computeBoundingSphere();const mesh=new THREE.Mesh(geometry,materials);mesh.name=chunk.name;mesh.castShadow=true;mesh.receiveShadow=true;group.add(mesh);}
 return group;}
function laneLength(points){return points.slice(1).reduce((total,p,i)=>total+Math.hypot(p.X-points[i].X,p.Y-points[i].Y),0);}
function laneAt(points,d){for(let i=1;i<points.length;i++){const a=points[i-1],b=points[i],length=Math.hypot(b.X-a.X,b.Y-a.Y);if(d<=length)return {X:a.X+(b.X-a.X)*d/length,Y:a.Y+(b.Y-a.Y)*d/length};d-=length;}return points.at(-1);}
function build(){environment=prototypes.get('Environment').clone(true);worldGroup.add(environment,mapActors);scene.add(worldGroup,galleryActors);for(let team=0;team<2;team++){const suffix=team?'Red':'Blue';instance('Core'+suffix,P(layout.Bases[team],.24),mapActors,{info:{name:team?'Красное ядро':'Синее ядро',type:'ГЛАВНАЯ БАЗА',description:'Укреплённая база: кристальное ядро, появление героев, восстановление и доступ к магазину.'}});for(let lane=0;lane<3;lane++){const points=layout.Lanes[lane].Points,length=laneLength(points);for(let tier=0;tier<3;tier++){const d=14+(2-tier)*15;instance('Tower'+suffix,P(laneAt(points,team?length-d:d),.24),mapActors,{info:{name:`${team?'Красная':'Синяя'} башня T${tier+1}`,type:'УКРЕПЛЕНИЯ ЛИНИИ',description:'Каменная башня с кристаллом и золотой оправой. В матче атакует противников и защищает следующий уровень укреплений.'}});}}for(let i=0;i<5;i++){const p={X:layout.Bases[team].X+(team?-i:i),Y:layout.Bases[team].Y};instance((i%2?'Mage':'Warrior')+suffix,P(p,.24),mapActors,{living:true,info:{name:i%2?'Тестовый маг':'Тестовый воин',type:'ГЕРОЙ',description:'Модель героя для локального матча в Unity.'}});}}
 const campCounts=[1,3,3,1,2,1];layout.Camps.forEach((p,i)=>{const name=creatureNames[i%6],count=campCounts[i%6],side=i<6?1:-1;for(let j=0;j<count;j++){const q=i%6===2?{X:p.X,Y:p.Y-j*1.4*side}:{X:p.X+j*1.4*side,Y:p.Y};const go=instance(name,P(q,.15),mapActors,{living:true,info:{name:info[name][0],type:`ЛАГЕРЬ ${i+1} · ${count} ${count===1?'СУЩЕСТВО':'СУЩЕСТВА'}`,description:info[name][1]}});if(name==='MoonWolf')go.scale.setScalar(j===0?1.12:.85);}label(String(i+1),P(p,4),i<6?'blue':'red');});
 layout.RiftCreatures.forEach((p,i)=>{const name=i?'RiftRay':'ObserverFirefly';instance(name,P(p,.3),mapActors,{living:true,floating:true,info:{name:info[name][0],type:'СУЩЕСТВО РАЗЛОМА',description:info[name][1]}});});layout.Bosses.forEach((p,i)=>{const name=i?'NightLeviathan':'SolarColossus',go=instance(name,P(p,.25),mapActors,{living:true,floating:!!i,info:{name:info[name][0],type:i?'АРЕНА БЕЗДНЫ':'АРЕНА РАССВЕТА',description:info[name][1]}});if(i)go.scale.setScalar(1.3);label(i?'Ночной левиафан':'Солнечный колосс',P(p,7),'boss');});
 layout.Crystals.forEach((p,i)=>{const go=instance('CrystalGate',P(p),mapActors,{crystal:i,info:{name:`Кристальный проход ${i+1}`,type:'РАЗРУШАЕМОЕ ПРЕПЯТСТВИЕ',description:'24 прочности. Шесть ближних или восемь дальних обычных атак. Восстанавливается через 60 секунд.'}});crystals.push({go,hp:24,restore:0});});layout.Bridges.forEach((p,i)=>{const go=instance('Bridge',P(p,-.45),mapActors,{info:{name:i?'Мост Сумерек':'Мост Рассвета',type:'ДИНАМИЧЕСКИЙ ЛЕСНОЙ ПУТЬ',description:'В матче мосты закрыты до 2:00, затем чередуются каждые 120 секунд. Можно переключить их в панели осмотра.'}});go.rotation.y=-Math.PI/4;bridges.push(go);label(i?'Мост Сумерек':'Мост Рассвета',P(p,1.8));});setBridge('none');
 creatureNames.forEach((name,i)=>{const p=new THREE.Vector3((i%5-2)*9,0,-Math.floor(i/5)*10),go=instance(name,p,galleryActors,{living:true,floating:['RiftGhost','ObserverFirefly','RiftRay','NightLeviathan'].includes(name),info:{name:info[name][0],type:i>=8?'ЭПИЧЕСКИЙ БОСС':'ОБИТАТЕЛЬ ДОЛИНЫ',description:info[name][1]}});if(i>=8)go.scale.setScalar(.72);const pedestal=new THREE.Mesh(new THREE.CylinderGeometry(3.3,3.4,.4,32),new THREE.MeshStandardMaterial({color:0x53634f,roughness:.9,metalness:.1}));pedestal.position.set(p.x,-.2,p.z);pedestal.receiveShadow=true;galleryActors.add(pedestal);label(info[name][0],new THREE.Vector3(p.x,0,p.z+4.1),'gallery','creatures');const button=document.createElement('button');button.textContent=info[name][0];button.onclick=()=>{document.querySelectorAll('#creature-list button').forEach(b=>b.classList.toggle('active',b===button));const focus=go.position.clone().add(new THREE.Vector3(0,1.2,0));animateCamera(focus,new THREE.Vector3(0,9,13),3.5);select(go);};$('creature-list').append(button);});
 selectionRing=new THREE.Mesh(new THREE.RingGeometry(2,2.12,64),new THREE.MeshBasicMaterial({color:0xe3c17e,side:THREE.DoubleSide,transparent:true,opacity:.85,depthTest:false}));selectionRing.rotation.x=-Math.PI/2;selectionRing.visible=false;selectionRing.renderOrder=9;scene.add(selectionRing);}
function animateCamera(target,offset,zoom=1){tween={start:performance.now(),targetFrom:controls.target.clone(),positionFrom:camera.position.clone(),zoomFrom:camera.zoom,targetTo:target,positionTo:target.clone().add(offset),zoomTo:zoom};}
function preset(name){document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));selected=null;$('selection').hidden=true;if(selectionRing)selectionRing.visible=false;if(name==='overview')animateCamera(new THREE.Vector3(0,0,0),new THREE.Vector3(0,140,98),1);if(name==='forest')animateCamera(P({X:-27,Y:5},1),new THREE.Vector3(-8,38,41),2.3);if(name==='dawn')animateCamera(P(layout.Bosses[0],1),new THREE.Vector3(0,24,26),3.2);if(name==='dusk')animateCamera(P(layout.Bosses[1],1),new THREE.Vector3(0,24,26),3.2);}
function setBridge(next){bridgeState=next;bridges.forEach((go,i)=>go.visible=next===(i?'dusk':'dawn'));document.querySelectorAll('[data-bridge]').forEach(b=>b.classList.toggle('active',b.dataset.bridge===next));}
function select(go){selected=go;const item=go.userData.info;if(!item)return;$('selection').hidden=false;$('selection-name').textContent=item.name;$('selection-type').textContent=item.type;$('selection-description').textContent=item.description;const crystal=go.userData.crystal;$('crystal-tools').hidden=crystal===undefined;selectionRing.position.copy(go.position);selectionRing.position.y=.32;selectionRing.visible=true;selectionRing.scale.setScalar(item.type.includes('БОСС')||item.type.includes('АРЕНА')?2:1);if(crystal!==undefined)updateCrystal();}
function updateCrystal(){if(selected?.userData.crystal===undefined)return;const c=crystals[selected.userData.crystal];$('durability-fill').style.width=`${c.hp/24*100}%`;$('durability-value').textContent=c.hp>0?`${c.hp} / 24`:`Проход открыт · восстановление через ${Math.max(0,Math.ceil(c.restore-clock))} с`;}
function hitCrystal(amount){if(selected?.userData.crystal===undefined)return;const c=crystals[selected.userData.crystal];if(c.hp<=0)return;c.hp=Math.max(0,c.hp-amount);if(c.hp===0){c.restore=clock+60;c.go.visible=false;}updateCrystal();}
function setMode(next){wantedMode=next;document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===next));$('render-gallery').hidden=next!=='renders';$('panel').hidden=next==='renders';$('toggle-panel').hidden=next==='renders';$('labels').hidden=next==='renders';document.querySelector('.viewer-tools').hidden=next==='renders';$('help').hidden=next==='renders';if(!ready){if(next==='renders')$('loading').hidden=true;return;}mode=next;worldGroup.visible=mode==='map';galleryActors.visible=mode==='creatures';$('selection').hidden=true;selected=null;selectionRing.visible=false;$('map-tools').hidden=next!=='map';$('creature-tools').hidden=next!=='creatures';if(next==='map')preset('overview');if(next==='creatures')animateCamera(new THREE.Vector3(0,1,-4),new THREE.Vector3(0,40,48),1.8);}
function resize(){const aspect=innerWidth/innerHeight,size=Math.max(46,71/aspect);camera.left=-size*aspect;camera.right=size*aspect;camera.top=size;camera.bottom=-size;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);}
function setupUI(){for(const b of document.querySelectorAll('[data-mode]'))b.onclick=()=>setMode(b.dataset.mode);for(const b of document.querySelectorAll('[data-view]'))b.onclick=()=>ready&&preset(b.dataset.view);for(const b of document.querySelectorAll('[data-bridge]'))b.onclick=()=>ready&&setBridge(b.dataset.bridge);$('toggle-panel').onclick=()=>{document.body.classList.toggle('panel-hidden');$('toggle-panel').textContent=document.body.classList.contains('panel-hidden')?'›':'‹';};$('show-labels').onchange=e=>showLabels=e.target.checked;$('zoom-in').onclick=()=>{camera.zoom=Math.min(12,camera.zoom*1.25);camera.updateProjectionMatrix();};$('zoom-out').onclick=()=>{camera.zoom=Math.max(.65,camera.zoom/1.25);camera.updateProjectionMatrix();};$('reset-camera').onclick=()=>setMode(mode);$('clear-selection').onclick=()=>{selected=null;$('selection').hidden=true;selectionRing.visible=false;};$('hit-melee').onclick=()=>hitCrystal(4);$('hit-ranged').onclick=()=>hitCrystal(3);$('restore').onclick=()=>{if(selected?.userData.crystal===undefined)return;const c=crystals[selected.userData.crystal];c.hp=24;c.go.visible=true;updateCrystal();};$('show-renders').onclick=()=>{$('error').hidden=true;setMode('renders');};
 let down=null;$('scene').addEventListener('pointerdown',e=>down={x:e.clientX,y:e.clientY});$('scene').addEventListener('pointerup',e=>{if(!ready||!down||Math.hypot(e.clientX-down.x,e.clientY-down.y)>7)return;const p=new THREE.Vector2(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1);ray.setFromCamera(p,camera);const hits=ray.intersectObjects((mode==='creatures'?galleryActors:mapActors).children,true);for(const hit of hits){let object=hit.object;while(object&&object!==scene&&!object.userData.info)object=object.parent;if(object?.userData.info){select(object);return;}}});window.addEventListener('resize',()=>ready&&resize());if(matchMedia('(pointer:coarse)').matches)$('help').textContent='Пальцем — вращение · Двумя пальцами — масштаб и перемещение · Нажми на существо';if(innerWidth<700)document.body.classList.add('panel-hidden');}
function frame(now){requestAnimationFrame(frame);const dt=Math.min(.1,(now-lastTime)/1000||0);lastTime=now;clock+=dt;if(tween){const t=Math.min(1,(now-tween.start)/850),v=t*t*(3-2*t);camera.position.lerpVectors(tween.positionFrom,tween.positionTo,v);controls.target.lerpVectors(tween.targetFrom,tween.targetTo,v);camera.zoom=THREE.MathUtils.lerp(tween.zoomFrom,tween.zoomTo,v);camera.updateProjectionMatrix();if(t===1)tween=null;}controls.update();for(const group of [mapActors,galleryActors])if(group.visible)for(const go of group.children)if(go.userData.living){go.position.y=go.userData.originY+Math.sin(clock*(go.userData.floating?1.6:2.2)+go.userData.phase)*(go.userData.floating?.15:.025);}for(const c of crystals)if(c.hp===0&&clock>=c.restore){c.hp=24;c.go.visible=true;}updateCrystal();for(const item of labels){const shown=showLabels&&item.group===mode,p=item.p.clone().project(camera);item.element.style.display=shown&&p.z>-1&&p.z<1?'block':'none';item.element.style.left=`${(p.x*.5+.5)*innerWidth}px`;item.element.style.top=`${(-p.y*.5+.5)*innerHeight}px`;}if(mode!=='renders')renderer.render(scene,camera);}
async function start(){setupUI();try{const [manifest,data]=await Promise.all([fetch('manifest.json').then(r=>r.json()),fetch('layout.json').then(r=>r.json())]);layout=data;const textureLoader=new THREE.TextureLoader();await Promise.all(manifest.Materials.map(async spec=>{const texture=await textureLoader.loadAsync('textures/'+spec.Texture+'.png');texture.colorSpace=THREE.SRGBColorSpace;texture.wrapS=texture.wrapT=THREE.RepeatWrapping;texture.anisotropy=4;const material=new THREE.MeshStandardMaterial({color:0xffffff,map:texture,vertexColors:true,roughness:['Crystal','Metal','Water'].includes(spec.Name)?.42:.83,metalness:spec.Name==='Metal'?.4:spec.Name==='Crystal'?.1:0,side:THREE.DoubleSide,emissive:spec.Emission?0xffffff:0,emissiveMap:spec.Emission?texture:null,emissiveIntensity:spec.Emission*.55});if(spec.Emission)material.onBeforeCompile=shader=>{shader.fragmentShader=shader.fragmentShader.replace('#include <emissivemap_fragment>','#include <emissivemap_fragment>\n totalEmissiveRadiance *= vColor.rgb;');};palette.set(spec.Name,material);}));
 let loaded=0;const queue=[...manifest.Models];async function worker(){while(queue.length){const model=queue.shift(),group=await readModel(model.WebFile);prototypes.set(model.Name,group);loaded++;$('load-progress').style.width=`${loaded/manifest.Models.length*100}%`;$('loading-status').textContent=`Сцена и существа · ${loaded} / ${manifest.Models.length}`;}}await Promise.all([worker(),worker(),worker()]);renderer=new THREE.WebGLRenderer({canvas:$('scene'),antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.2;scene=new THREE.Scene();scene.background=new THREE.Color(0x18363d);scene.fog=new THREE.Fog(0x18363d,190,340);camera=new THREE.OrthographicCamera(-90,90,60,-60,.1,450);camera.position.set(0,140,98);controls=new OrbitControls(camera,$('scene'));controls.enableDamping=true;controls.dampingFactor=.075;controls.minPolarAngle=.12;controls.maxPolarAngle=1.35;controls.minZoom=.65;controls.maxZoom=12;controls.addEventListener('start',()=>tween=null);scene.add(new THREE.HemisphereLight(0xc7dfdc,0x48653b,1.4));const sun=new THREE.DirectionalLight(0xffe3ac,2.3);sun.position.set(-40,95,35);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-85;sun.shadow.camera.right=85;sun.shadow.camera.top=85;sun.shadow.camera.bottom=-85;sun.shadow.camera.near=1;sun.shadow.camera.far=250;sun.shadow.normalBias=.05;sun.shadow.bias=-.00015;scene.add(sun);build();resize();ready=true;$('loading').hidden=true;setMode(wantedMode);requestAnimationFrame(frame);}catch(error){console.error(error);$('loading').hidden=true;$('error').hidden=false;}}
start();
